DDL = "\nCREATE TABLE classic_frame_media_links (\n project_id uuid NOT NULL,\n id uuid NOT NULL,\n target_media_id uuid NOT NULL,\n source_project_id uuid NOT NULL,\n source_media_id uuid NOT NULL,\n blob_id uuid NOT NULL,\n sha256 varchar(64) NOT NULL,\n source_form_version_id uuid,\n source_workflow_version_id uuid,\n source_unit_key text,\n source_purpose text,\n shot_id uuid NOT NULL,\n role text NOT NULL,\n command_key text NOT NULL,\n created_by text NOT NULL,\n created_at timestamptz NOT NULL DEFAULT now(),\n CONSTRAINT pk_classic_frame_media_links PRIMARY KEY (project_id,id),\n CONSTRAINT fk_classic_frame_media_links_project_id_projects FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT,\n CONSTRAINT uq_classic_frame_media_target UNIQUE (project_id,target_media_id),\n CONSTRAINT uq_classic_frame_media_command UNIQUE (project_id,command_key),\n CONSTRAINT fk_classic_frame_media_source FOREIGN KEY (source_project_id,source_media_id,blob_id)\n   REFERENCES media_items(project_id,id,blob_id) ON DELETE RESTRICT,\n CONSTRAINT fk_classic_frame_media_target FOREIGN KEY (project_id,target_media_id,blob_id)\n   REFERENCES media_items(project_id,id,blob_id) ON DELETE RESTRICT,\n CONSTRAINT fk_classic_frame_media_hash FOREIGN KEY (blob_id,sha256)\n   REFERENCES media_blobs(id,sha256) ON DELETE RESTRICT,\n CONSTRAINT fk_classic_frame_media_form FOREIGN KEY (source_project_id,source_form_version_id)\n   REFERENCES asset_card_form_versions(project_id,id) ON DELETE RESTRICT,\n CONSTRAINT fk_classic_frame_media_block FOREIGN KEY\n   (source_project_id,source_workflow_version_id,source_unit_key,source_purpose,source_media_id)\n   REFERENCES intelligent_media(project_id,version_id,unit_key,purpose,media_id) ON DELETE RESTRICT,\n CONSTRAINT fk_classic_frame_media_links_project_id_shot_id_shots FOREIGN KEY (project_id,shot_id)\n   REFERENCES shots(project_id,id) ON DELETE RESTRICT,\n CONSTRAINT fk_classic_frame_media_receipt FOREIGN KEY (project_id,command_key)\n   REFERENCES command_receipts(project_id,idempotency_key) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED,\n CONSTRAINT ck_classic_frame_media_links_scope CHECK (project_id<>source_project_id),\n CONSTRAINT ck_classic_frame_media_links_source_shape CHECK (\n   (source_form_version_id IS NOT NULL AND source_workflow_version_id IS NULL AND source_unit_key IS NULL AND source_purpose IS NULL)\n   OR (source_form_version_id IS NULL AND source_workflow_version_id IS NOT NULL AND source_unit_key IS NOT NULL AND source_purpose IS NOT DISTINCT FROM 'blocking')),\n CONSTRAINT ck_classic_frame_media_links_frame CHECK (role IN ('first_frame','last_frame') AND length(btrim(command_key)) BETWEEN 1 AND 200 AND length(btrim(created_by)) BETWEEN 1 AND 200),\n CONSTRAINT ck_classic_frame_media_links_sha256_format CHECK (sha256 IS NULL OR sha256 ~ '^[0-9a-f]{64}$')\n);\nCREATE INDEX ix_classic_frame_media_source_project ON classic_frame_media_links(project_id,source_project_id);\nCREATE INDEX ix_classic_frame_media_source_media ON classic_frame_media_links(source_project_id,source_media_id);\n\nCREATE FUNCTION vsc_classic_frame_media_link_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE form_media uuid; unit_kind text; source_type text; target_type text;\nBEGIN\n SELECT modality INTO source_type FROM media_items WHERE project_id=NEW.source_project_id AND id=NEW.source_media_id;\n SELECT modality INTO target_type FROM media_items WHERE project_id=NEW.project_id AND id=NEW.target_media_id;\n IF source_type IS DISTINCT FROM 'image' OR target_type IS DISTINCT FROM 'image' THEN\n  RAISE EXCEPTION 'classic frame requires an image' USING ERRCODE='23514';\n END IF;\n IF NEW.source_form_version_id IS NOT NULL THEN\n  SELECT media_id INTO form_media FROM asset_card_form_versions\n   WHERE project_id=NEW.source_project_id AND id=NEW.source_form_version_id;\n  IF form_media IS DISTINCT FROM NEW.source_media_id THEN\n   RAISE EXCEPTION 'source asset form media mismatch' USING ERRCODE='23514';\n  END IF;\n ELSE\n  SELECT kind INTO unit_kind FROM intelligent_units\n   WHERE project_id=NEW.source_project_id AND version_id=NEW.source_workflow_version_id AND unit_key=NEW.source_unit_key;\n  IF unit_kind IS DISTINCT FROM 'blocking' THEN\n   RAISE EXCEPTION 'source is not a blocking image' USING ERRCODE='23514';\n  END IF;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER classic_frame_media_link_guard BEFORE INSERT ON classic_frame_media_links\n FOR EACH ROW EXECUTE FUNCTION vsc_classic_frame_media_link_guard();\nCREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON classic_frame_media_links\n FOR EACH ROW EXECUTE FUNCTION vsc_reject_mutation();\n\nCREATE FUNCTION vsc_classic_frame_media_receipt_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF NOT EXISTS (\n  SELECT 1 FROM command_receipts r\n  JOIN project_revisions rev ON rev.project_id=r.project_id AND rev.command_key=r.idempotency_key\n  WHERE r.project_id=NEW.project_id AND r.idempotency_key=NEW.command_key\n   AND rev.action='import_classic_frame_media'\n   AND r.response->>'revision'=rev.revision::text\n   AND r.response->>'media_id'=NEW.target_media_id::text\n   AND r.response->>'sha256'=NEW.sha256\n   AND r.response->>'shot_id'=NEW.shot_id::text\n   AND r.response->>'role'=NEW.role\n   AND r.response->>'source_project_id'=NEW.source_project_id::text\n   AND r.response->>'source_media_id'=NEW.source_media_id::text\n   AND r.response->>'modality'='image'\n ) THEN RAISE EXCEPTION 'classic frame media receipt mismatch' USING ERRCODE='23514'; END IF;\n RETURN NULL;\nEND $$;\nCREATE CONSTRAINT TRIGGER classic_frame_media_receipt_guard\n AFTER INSERT ON classic_frame_media_links DEFERRABLE INITIALLY DEFERRED\n FOR EACH ROW EXECUTE FUNCTION vsc_classic_frame_media_receipt_guard();\n"
LIBRARY_PRIOR_GUARD = "CREATE OR REPLACE FUNCTION vsc_library_has_imported_ancestor(p_project_id uuid, p_media_id uuid)\nRETURNS boolean LANGUAGE sql STABLE AS $$\nWITH RECURSIVE edges AS NOT MATERIALIZED (\n\n SELECT c.project_id AS target_project, t.media_id AS target_media,\n        c.source_project_id AS source_project, s.media_id AS source_media\n FROM asset_card_copy_sources c\n JOIN asset_card_form_versions t ON t.project_id=c.project_id AND t.id=c.target_form_version_id\n JOIN asset_card_form_versions s ON s.project_id=c.source_project_id AND s.id=c.source_form_version_id\n WHERE t.media_id IS NOT NULL AND s.media_id IS NOT NULL\n UNION\n SELECT c.project_id, tv.reference_media_id, c.source_project_id, sv.reference_media_id\n FROM asset_card_copy_sources c\n JOIN asset_card_form_versions t ON t.project_id=c.project_id AND t.id=c.target_form_version_id\n JOIN asset_card_form_versions s ON s.project_id=c.source_project_id AND s.id=c.source_form_version_id\n JOIN voice_spec_versions tv ON tv.project_id=t.project_id AND tv.id=t.voice_spec_id\n JOIN voice_spec_versions sv ON sv.project_id=s.project_id AND sv.id=s.voice_spec_id\n WHERE tv.reference_media_id IS NOT NULL AND sv.reference_media_id IS NOT NULL\n UNION\n SELECT project_id,target_media_id,source_project_id,source_media_id FROM template_copy_media\n UNION\n SELECT project_id,target_media_id,source_project_id,source_media_id FROM canvas_project_media_links\n\n UNION ALL\n SELECT o.project_id,o.media_id,i.project_id,i.media_id FROM operation_outputs o JOIN operation_inputs i ON i.project_id=o.project_id AND i.operation_id=o.operation_id\n UNION ALL\n SELECT o.project_id,o.media_id,i.project_id,i.media_id FROM job_outputs o JOIN job_input_media i ON i.project_id=o.project_id AND i.job_id=o.job_id\n), ancestors(project_id,media_id) AS (\n SELECT p_project_id,p_media_id\n UNION\n SELECT e.source_project,e.source_media FROM ancestors a JOIN edges e ON e.target_project=a.project_id AND e.target_media=a.media_id\n)\nSELECT EXISTS(SELECT 1 FROM ancestors a JOIN library_reuses r ON r.project_id=a.project_id AND r.media_id=a.media_id WHERE r.library_version_id IS NOT NULL AND r.reuse_mode IN ('reference','derive'))\n$$\n"
